return [
  { json: { source: 'video_alpha', title: 'AI inbox triage for a small agency', url: 'https://example.invalid/signals/inbox-triage?utm_source=demo', published_at: '2026-07-24T08:00:00Z', engagement: 86 } },
  { json: { source: 'video_alpha', title: 'AI inbox triage for a small agency', url: 'https://example.invalid/signals/inbox-triage?utm_campaign=duplicate', published_at: '2026-07-24T08:00:00Z', engagement: 86 } },
  { json: { source: 'forum_beta', title: 'Human approval gates for invoice automation', url: 'https://example.invalid/signals/invoice-approval', published_at: '2026-07-25T10:30:00Z', engagement: 71 } },
  { json: { source: 'newsletter_gamma', title: 'Evidence receipts for workflow repairs', url: 'https://example.invalid/signals/evidence-receipts', published_at: '2026-07-26T06:15:00Z', engagement: 94 } },
  { json: { source: 'forum_beta', title: '', url: 'https://example.invalid/signals/missing-title', published_at: '2026-07-26T09:00:00Z', engagement: 12 } }
];

const seen = new Set();
const normalized = [];
for (const item of items) {
  const row = item.json;
  const title = String(row.title || '').trim().replace(/\s+/g, ' ');
  let cleanUrl;
  try {
    const parsed = new URL(String(row.url || ''));
    parsed.search = '';
    parsed.hash = '';
    cleanUrl = parsed.toString();
  } catch {
    cleanUrl = '';
  }
  const stableKey = `${String(row.source || '').toLowerCase()}|${cleanUrl.toLowerCase()}`;
  if (seen.has(stableKey)) continue;
  seen.add(stableKey);
  normalized.push({
    json: {
      source: String(row.source || '').toLowerCase(),
      title,
      url: cleanUrl,
      published_at: row.published_at,
      engagement: Number(row.engagement || 0),
      stable_key: stableKey
    }
  });
}
return normalized;

const referenceTime = Date.parse('2026-07-27T00:00:00Z');
return items.map((item) => {
  const row = item.json;
  const ageHours = Math.max(0, (referenceTime - Date.parse(row.published_at)) / 3600000);
  const recency = Math.max(0, 100 - ageHours * 1.25);
  const completeness = row.title && row.url && row.source ? 100 : 0;
  const score = Math.round((recency * 0.45 + Math.min(row.engagement, 100) * 0.35 + completeness * 0.2) * 100) / 100;
  const needsReview = completeness === 0 || score < 55;
  return { json: { ...row, score, needs_review: needsReview, decision_reason: needsReview ? 'Missing required evidence or score below 55' : 'Evidence complete and score at least 55' } };
});
